import {catalogueOptions} from './matcher.mjs';
import {createPlanner,parseBrief,assess,reasonText} from './planner.mjs';
const $=s=>document.querySelector(s),form=$('#match-form'),dialog=$('#profile-dialog');
const money=n=>new Intl.NumberFormat('ru-RU').format(n),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const date=d=>new Intl.DateTimeFormat('ru-RU',{day:'numeric',month:'long',timeZone:'UTC'}).format(new Date(d+'T00:00:00Z'));
let catalogue=[],options,planner,result,activeTab='selection',excludedFilter='all',previousRequest=null,currentProfile=null;
const defaultRequest={city:'Алматы',date:'2026-10-15',category:'Ведущий',event_format:'корпоратив',budget_kzt:1200000,duration_hours:'',language:'',brief:'спокойный ведущий делового форума'};
const statusLabel={confirmed:'Указано в профиле',related:'Есть близкое описание',unknown:'Не указано',conflict:'Есть противоречие'};
function updateCategories(preferred=form.elements.category.value){if(!options)return;const available=options.categories_by_city[form.elements.city.value]||[],all=[...new Set(Object.values(options.categories_by_city).flat())].sort((a,b)=>a.localeCompare(b,'ru'));const absent=all.filter(c=>!available.includes(c)),option=c=>`<option value="${esc(c)}">${esc(c)}</option>`;form.elements.category.innerHTML=`<optgroup label="Есть в городе">${available.map(option).join('')}</optgroup>${absent.length?`<optgroup label="Нет в этом городе">${absent.map(option).join('')}</optgroup>`:''}`;form.elements.category.value=all.includes(preferred)?preferred:available[0];}
function showBrief(){const parsed=parseBrief(form.elements.brief.value);$('#brief-preview').innerHTML=parsed.map(p=>`<span>${p.kind==='condition'?'Условие':'Пожелание'}: ${esc(p.label)}</span>`).join('');}
function writeForm(r){form.elements.city.value=r.city;updateCategories(r.category);for(const [key,value] of Object.entries(r)){const field=form.elements.namedItem(key);if(field)field.value=value??'';}showBrief();}
function provenance(p){return `<div class="provenance">${p.synthetic?'<span>Синтетический профиль</span>':''}${p.city_imputed?'<span>Город восстановлен в датасете</span>':''}${p.price_imputed?'<span>Стартовая цена оценочная</span>':''}</div>`;}
function priceLabel(p){return `от ${money(p.price_from_kzt)} ₸`;}
function cautions(p){return assess(p,result.parsed).filter(c=>c.status==='unknown'||c.status==='conflict').map(c=>`${c.label}: ${c.status==='conflict'?'есть противоречие в описании':'не указано в описании'}`).slice(0,2);}
function card(p,i){return `<article class="card"><div class="card-header"><span class="rank-no" aria-hidden="true">0${i+1}</span><div class="card-name"><h3>${esc(p.name)}</h3><p>${esc(result.request.category)} / ${esc(p.city)}</p></div><div class="card-price"><strong>${priceLabel(p)}</strong><small>${p.price_imputed?'Оценочная стартовая цена':'Стартовая цена'}</small></div></div><div class="card-facts"><span class="fact">✓ ${date(result.request.date)} по каталогу</span><span class="fact">✓ ${esc(result.request.event_format)}</span>${result.request.language?`<span class="fact">✓ ${esc(result.request.language)}</span>`:''}<span class="fact">✓ Стартовая цена в бюджете</span></div><div class="card-inside"><div><span class="micro-label">Описание</span><blockquote class="card-quote">«${esc(p.evidence_quote)}»</blockquote></div>${cautions(p).length?`<div class="card-cautions"><span class="micro-label">Пожелания</span>${cautions(p).map(s=>`<p>${esc(s)}</p>`).join('')}</div>`:''}</div>${provenance(p)}<button type="button" class="card-action" data-profile="${esc(p.id)}">Подробнее <span>↗</span></button></article>`;}
function setTab(tab,focus=false){activeTab=tab;document.querySelectorAll('[data-tab]').forEach(b=>{const selected=b.dataset.tab===tab;b.setAttribute('aria-selected',String(selected));b.tabIndex=selected?0:-1;if(selected&&focus)b.focus();});for(const id of ['selection','excluded','alternatives'])$('#panel-'+id).hidden=id!==tab;}
function renderSelection(){const panel=$('#panel-selection');let html='';if(previousRequest)html+='<button type="button" class="undo" data-undo>↶ Вернуть исходные условия</button>';if(!result.cards.length)html+=`<div class="empty"><span class="empty-symbol">…</span><h3>${result.status==='category_absent'?'В этом городе нет выбранной категории.':'Подрядчики не найдены.'}</h3><p>${result.status==='category_absent'?'Выберите другой город или категорию.':'Посмотрите ближайшие даты, похожий формат или немного больший бюджет.'}</p></div>`;else html+=result.cards.map(card).join('');if(result.alternatives.length)html+=`<div class="plan-invite"><p><b>Можно изменить условия</b>Подходящие варианты: ${result.alternatives.length}.</p><button type="button" data-open-plan>Посмотреть варианты ↗</button></div>`;else if(!result.cards.length)html+='<p class="tab-intro">Близких вариантов не найдено. Попробуйте другой город, категорию или бюджет.</p>';panel.innerHTML=html;}
function renderExcluded(){const reasons=[...new Set(result.excluded.flatMap(p=>p.failures))];const rows=result.excluded.filter(p=>excludedFilter==='all'||excludedFilter==='eligible'&&!p.failures.length||p.failures.includes(excludedFilter));$('#panel-excluded').innerHTML=`<div class="tab-intro"><h3>Остальные подрядчики</h3><p>${esc(result.request.category)} · ${esc(result.request.city)}. Нажмите на имя, чтобы открыть резюме и узнать, почему подрядчик не вошёл в рекомендации.</p></div><div class="filter-row"><button type="button" data-filter="all" aria-pressed="${excludedFilter==='all'}">Все · ${result.excluded.length}</button>${result.excluded.some(p=>!p.failures.length)?`<button type="button" data-filter="eligible" aria-pressed="${excludedFilter==='eligible'}">Тоже подходят</button>`:''}${reasons.map(k=>`<button type="button" data-filter="${k}" aria-pressed="${excludedFilter===k}">${esc(reasonText[k])}</button>`).join('')}</div>${rows.length?rows.map(p=>`<button type="button" class="excluded-row" data-profile="${esc(p.id)}"><span><b>${esc(p.name)}</b><small>${p.failures.length?p.failures.map(k=>esc(reasonText[k])).join(' · '):'Подходит по условиям · не вошёл в первые три'}</small></span><span class="row-price">от ${money(p.price_from_kzt)} ₸<span>↗</span></span></button>`).join(''):'<div class="empty"><p>Нет подрядчиков с этой причиной.</p></div>'}`;}
function patchText(a){return Object.entries(a.patch).map(([key,value])=>({date:()=>`${date(result.request.date)} → ${date(value)}`,budget_kzt:()=>`${money(result.request.budget_kzt)} → ${money(value)} ₸`,duration_hours:()=>`${result.request.duration_hours} → ${value} ч`,city:()=>`${result.request.city} → ${value}`,event_format:()=>`${result.request.event_format} → ${value}`}[key]())).join('<br>');}
function renderAlternatives(){const types={date:'Ближайшая дата',budget:'Ближайшая цена',duration:'Меньше часов',format:'Похожий формат',combined:'Несколько изменений'};$('#panel-alternatives').innerHTML=`<div class="tab-intro"><h3>Варианты с другими условиями</h3><p>Проверяем даты в пределах недели, похожие форматы и бюджет не более чем на 25% выше. Условия меняются только после вашего выбора.</p></div>${previousRequest?'<button type="button" class="undo" data-undo>↶ Вернуть исходные условия</button>':''}${result.alternatives.map((a,i)=>`<article class="alternative"><div><div class="alt-type">${types[a.kind]||'Другие условия'}</div><h4>${patchText(a)}</h4><p>${a.kind==='combined'?'Изменения нужно применить вместе.':a.kind==='date'?'Ближайшая дата, на которую подходит больше подрядчиков.':a.kind==='budget'?'Наименьшее повышение бюджета в пределах 25%, которое увеличивает выбор.':a.kind==='duration'?'Сокращение не более чем на два часа.':a.kind==='format'?'Это другой формат события. Выбирайте его, только если он вам подходит.':''}</p></div><div class="alt-result">${a.count}<small>подходит · сейчас ${result.eligible}</small></div><button type="button" data-apply="${i}">Выбрать эти условия <span>↗</span></button></article>`).join('')||`<div class="empty"><h3>${result.eligible>=3?'Достаточно подходящих подрядчиков.':'Близких вариантов не найдено.'}</h3><p>${result.eligible>=3?'Уже подходят три или больше подрядчиков. Результаты доступны во вкладке «Рекомендации».':'Изменения в пределах недели и 25% бюджета, а также похожие форматы не увеличивают выбор. Можно изменить параметры поиска самостоятельно.'}</p></div>`}`;}
function render(){const r=result.request;$('#loading').hidden=true;$('#request-summary').innerHTML=[r.city,r.category,date(r.date)+' 2026',r.event_format,'бюджет '+money(r.budget_kzt)+' ₸',...(r.language?[r.language]:[]),...(r.duration_hours?[r.duration_hours+' ч']:[])].map(s=>`<span>${esc(s)}</span>`).join('')+(result.notes.length?`<p class="understanding-note">${result.notes.map(esc).join(' ')}</p>`:'');$('#selection-count').textContent=result.cards.length;$('#excluded-count').textContent=result.excluded.length;$('#alternative-count').textContent=result.alternatives.length;renderSelection();renderExcluded();renderAlternatives();setTab(activeTab);$('#update-status').textContent=`Подбор обновлён. Подходят ${result.eligible} из ${result.total}. В рекомендациях: ${result.cards.map(p=>p.name).join(', ')||'никого'}.`;$('#form-error').textContent='';$('#dirty-note').hidden=true;}
function run(input,{keepPrevious=false}={}){if(!planner)throw Error('Каталог ещё загружается.');const next=planner(input);if(!keepPrevious)previousRequest=null;result=next;excludedFilter='all';writeForm(next.request);render();return result;}
function submit(){try{activeTab='selection';run(Object.fromEntries(new FormData(form)));if(matchMedia('(max-width:760px)').matches)$('.selection').scrollIntoView({behavior:'smooth'});}catch(e){$('#form-error').textContent=e.message;}}
form.addEventListener('submit',e=>{e.preventDefault();submit();});
form.elements.city.addEventListener('change',()=>updateCategories());
form.addEventListener('input',()=>{showBrief();$('#dirty-note').hidden=false;});form.addEventListener('change',()=>{$('#dirty-note').hidden=false;});
$('#reset').addEventListener('click',()=>{try{activeTab='selection';run(defaultRequest);}catch(e){$('#form-error').textContent=e.message;}});
function bindTabKeyboard(container,selector,action){container.addEventListener('keydown',e=>{if(!e.target.matches(selector)||!['ArrowRight','ArrowLeft','Home','End'].includes(e.key))return;e.preventDefault();const buttons=[...container.querySelectorAll(selector)],n=buttons.indexOf(e.target),index=e.key==='Home'?0:e.key==='End'?buttons.length-1:(n+(e.key==='ArrowRight'?1:-1)+buttons.length)%buttons.length;action(buttons[index]);buttons[index].focus();});}
document.querySelector('.navigation').addEventListener('click',e=>{const b=e.target.closest('[data-tab]');if(b)setTab(b.dataset.tab);});bindTabKeyboard($('.navigation'),'[data-tab]',b=>setTab(b.dataset.tab));
function openProfile(id){const p=catalogue.find(p=>p.id===id);if(!p)return;currentProfile=p;const findings=assess(p,result.parsed),excluded=result.excluded.find(c=>c.id===p.id),fail=excluded?.failures||[];$('#dialog-content').innerHTML=`<div class="dialog-head"><span class="micro-label">Резюме</span><h2 id="dialog-title">${esc(p.name)}</h2><p>${esc(p.categories.join(' · '))} · ${esc(p.city)}</p><p class="resume-price">${priceLabel(p)}</p></div><div class="dialog-panel"><dl class="detail-facts"><div><dt>Языки</dt><dd>${esc(p.languages.join(', '))}</dd></div><div><dt>Форматы событий</dt><dd>${esc(p.event_formats.join(', '))}</dd></div><div><dt>Длительность</dt><dd>${p.max_hours===null?'Не ограничена в каталоге':`До ${p.max_hours} ч`}</dd></div><div><dt>${date(result.request.date)}</dt><dd>${p.busy_dates.includes(result.request.date)?'Занят':'Доступен'} по календарю</dd></div></dl>${fail.length?`<p class="profile-note">Не вошёл в рекомендации: ${fail.map(k=>esc(reasonText[k])).join('; ')}.</p>`:excluded?'<p class="profile-note">Подходит по условиям, но не вошёл в первые три рекомендации.</p>':''}<h3>Описание</h3><p class="profile-description">${esc(p.description)}</p>${findings.length?`<h3>Ваши пожелания</h3><ul class="evidence-list">${findings.map(a=>`<li><strong>${esc(a.label)}</strong><span class="evidence-status ${a.status}">${statusLabel[a.status]}</span><small>${a.quote?esc(a.quote):'В описании нет подтверждения.'}</small></li>`).join('')}</ul>`:''}</div>`;dialog.showModal();dialog.scrollTop=0;}
$('.dialog-close').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',e=>{if(e.target===dialog){const rect=dialog.getBoundingClientRect();if(e.clientX<rect.left||e.clientX>rect.right||e.clientY<rect.top||e.clientY>rect.bottom)dialog.close();}});
document.addEventListener('click',e=>{const profile=e.target.closest('[data-profile]');if(profile)openProfile(profile.dataset.profile);const filter=e.target.closest('[data-filter]');if(filter){excludedFilter=filter.dataset.filter;renderExcluded();document.querySelector(`[data-filter="${excludedFilter}"]`)?.focus();}if(e.target.closest('[data-open-plan]'))setTab('alternatives',true);const apply=e.target.closest('[data-apply]');if(apply){const a=result.alternatives[Number(apply.dataset.apply)];previousRequest={...result.request};activeTab='selection';run({...result.request,...a.patch},{keepPrevious:true});$('#tab-selection').focus();}if(e.target.closest('[data-undo]')&&previousRequest){const restore=previousRequest;activeTab='selection';run(restore);$('#tab-selection').focus();}const demo=e.target.closest('[data-demo]');if(demo){const r={...defaultRequest};if(demo.dataset.demo==='december')r.date='2026-12-19';if(demo.dataset.demo==='empty')r.budget_kzt=600000;activeTab='selection';try{run(r);}catch(error){$('#form-error').textContent=error.message;}}});
async function init(){try{const response=await fetch('./catalogue.json');if(!response.ok)throw Error('Каталог не загрузился.');catalogue=await response.json();planner=createPlanner(catalogue);options=catalogueOptions(catalogue);form.elements.city.innerHTML=options.cities.map(c=>`<option>${esc(c)}</option>`).join('');$('#submit').disabled=false;run(defaultRequest);}catch(e){$('#loading').innerHTML='Не удалось загрузить каталог. <button type="button" id="retry">Повторить</button>';$('#retry').addEventListener('click',init);$('#form-error').textContent=e.message;}}
if(document.modelContext?.registerTool){const lifecycle=new AbortController();window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});try{Promise.resolve(document.modelContext.registerTool({name:'find_event_contractors',title:'Подобрать event-подрядчиков',description:'Run catalogue matching, update the visible brief and results, and return verified alternatives. Does not book or contact anyone.',inputSchema:{type:'object',properties:{city:{type:'string'},date:{type:'string'},event_format:{type:'string'},category:{type:'string'},budget_kzt:{type:'integer',minimum:1},duration_hours:{type:'number',exclusiveMinimum:0},language:{type:'string'},brief:{type:'string',maxLength:500}},required:['city','date','event_format','category','budget_kzt'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:true},execute(input){activeTab='selection';const r=run(input);return {status:r.status,eligible:r.eligible,cards:r.cards.map(p=>({id:p.id,name:p.name,starting_price:p.price_from_kzt})),parsed:r.parsed,alternatives:r.alternatives,excluded:r.excluded.map(p=>({id:p.id,name:p.name,reasons:p.failures}))};}},{signal:lifecycle.signal})).catch(()=>{});}catch{}}
showBrief();init();
